package bookstore

import (
	"context"
	"fmt"
	"sync"

	"github.com/google/uuid"
)

// Book represents a book in the bookstore.
type Book struct {
	ID    string `json:"id"`
	Title  string `json:"title" validate:"required,min=3"`
	Author string `json:"author" validate:"required,min=3"`
	Pages  int    `json:"pages" validate:"required,min=1"`
}

// CreateBookRequest represents the request body for creating a new book.
type CreateBookRequest struct {
	Title  string `json:"title" validate:"required,min=3"`
	Author string `json:"author" validate:"required,min=3"`
	Pages  int    `json:"pages" validate:"required,min=1"`
}

// BookStore defines the interface for managing books.
type BookStore interface {
	ListBooks(ctx context.Context) ([]Book, error)
	CreateBook(ctx context.Context, req CreateBookRequest) (Book, error)
	GetBook(ctx context.Context, id string) (Book, error)
}

// InMemBookStore is an in-memory implementation of BookStore.
type InMemBookStore struct {
	mu    sync.RWMutex
	books map[string]Book
}

// NewInMemBookStore creates a new InMemBookStore.
func NewInMemBookStore() *InMemBookStore {
	return &InMemBookStore{
		books: make(map[string]Book),
	}
}

// ListBooks returns all books in the store.
func (s *InMemBookStore) ListBooks(ctx context.Context) ([]Book, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()

	var bookList []Book
	for _, book := range s.books {
		bookList = append(bookList, book)
	}
	return bookList, nil
}

// CreateBook creates a new book and adds it to the store.
func (s *InMemBookStore) CreateBook(ctx context.Context, req CreateBookRequest) (Book, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	id := uuid.New().String()
	book := Book{
		ID:    id,
		Title:  req.Title,
		Author: req.Author,
		Pages:  req.Pages,
	}

	s.books[id] = book
	return book, nil
}

// GetBook retrieves a book by its ID.
func (s *InMemBookStore) GetBook(ctx context.Context, id string) (Book, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()

	book, ok := s.books[id]
	if !ok {
		return Book{}, fmt.Errorf("book with ID %s not found", id)
	}
	return book, nil
}

package bookstore

import (
	"encoding/json"
	"errors"
	"net/http"

	"github.com/go-chi/chi/v5"
	"github.com/go-playground/validator/v10"
)

// A Handlers holds all the http handlers for the book service.
type Handlers struct {
	Store    BookStore
	Validate *validator.Validate
}

// ListBooks returns a list of all books.
func (h *Handlers) ListBooks(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	books, err := h.Store.ListBooks(ctx)
	if err != nil {
		http.Error(w, "Internal Server Error", http.StatusInternalServerError)
		return
	}

	out, err := json.Marshal(books)
	if err != nil {
		http.Error(w, "Internal Server Error", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	w.Write(out)
}

// CreateBook creates a new book.
func (h *Handlers) CreateBook(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()

	var req CreateBookRequest
	err := json.NewDecoder(r.Body).Decode(&req)
	if err != nil {
		http.Error(w, "Bad Request", http.StatusBadRequest)
		return
	}

	if err := h.Validate.Struct(req); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	book, err := h.Store.CreateBook(ctx, req)
	if err != nil {
		http.Error(w, "Internal Server Error", http.StatusInternalServerError)
		return		
	}

	out, err := json.Marshal(book)
	if err != nil {
		http.Error(w, "Internal Server Error", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	w.Write(out)
}

// GetBook returns a single book by ID.
func (h *Handlers) GetBook(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	id := chi.URLParam(r, "id")

	book, err := h.Store.GetBook(ctx, id)
	if err != nil {
		if errors.Is(err, errors.New(fmt.Sprintf("book with ID %s not found", id))) {
			http.Error(w, "Book not found", http.StatusNotFound)
			return
		}
		http.Error(w, "Internal Server Error", http.StatusInternalServerError)
		return
	}

	out, err := json.Marshal(book)
	if err != nil {
		http.Error(w, "Internal Server Error", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	w.Write(out)
}

package main

import (
	"context"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"bookstore/internal/bookstore"

	"github.com/go-chi/chi/v5"
	"github.com/go-chi/chi/v5/middleware"
	"github.com/go-playground/validator/v10"
)

func main() {
	if err := run(); err != nil {
		log.Printf("server failed: %v", err)
		os.Exit(1)
	}
}

func run() error {
	// =========================================================================
	// Configuration

	// For simplicity, we'll hardcode the port for this example.
	const port = ":8080"

	// =========================================================================
	// Dependencies

	store := bookstore.NewInMemBookStore()
	validate := validator.New()

	h := &bookstore.Handlers{
		Store:    store,
		Validate: validate,
	}

	// =========================================================================
	// Router Setup

	r := chi.NewRouter()
	r.Use(middleware.Logger)
	r.Use(middleware.Recoverer)

	r.Get("/books", h.ListBooks)
	r.Post("/books", h.CreateBook)
	r.Get("/books/{id}", h.GetBook)

	// =========================================================================
	// Start Server

	httpServer := &http.Server{
		Addr:         port,
		Handler:      r,
		ReadTimeout:  5 * time.Second,
		WriteTimeout: 10 * time.Second,
		IdleTimeout:  120 * time.Second,
	}

	serverErrors := make(chan error, 1)

	go func() {
		log.Printf("main: API listening on %s", port)
		serverErrors <- httpServer.ListenAndServe()
	}()

	// =========================================================================
	// Shutdown

	shutdown := make(chan os.Signal, 1)
	signal.Notify(shutdown, os.Interrupt, syscall.SIGTERM)

	select {
	case err := <-serverErrors:
		return fmt.Errorf("server error: %w", err)

	case <-shutdown:
		log.Println("main: Start shutdown")

		// Give outstanding requests a minute to complete.
		ctx, cancel := context.WithTimeout(context.Background(), time.Minute)
		defer cancel()

		if err := httpServer.Shutdown(ctx); err != nil {
			httpServer.Close()
			return fmt.Errorf("could not stop server gracefully: %w", err)
		}
	}

	return nil
}

